import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.zip.CRC32;

public class ProbkaDeterministyczna {
    static boolean wProbce(String id) {
        CRC32 crc = new CRC32();
        crc.update(id.getBytes(StandardCharsets.UTF_8));
        return crc.getValue() % 100 == 0;
    }

    public static void main(String[] args) {
        List<String> probka1 = new ArrayList<>(), probka2 = new ArrayList<>();
        for (int i = 1; i <= 100_000; i++) if (wProbce(Integer.toString(i))) probka1.add(Integer.toString(i));
        for (int i = 1; i <= 100_000; i++) if (wProbce(Integer.toString(i))) probka2.add(Integer.toString(i));
        System.out.println("rozmiar: " + probka1.size() + ", identyczne: " + probka1.equals(probka2));
        System.out.println("pierwsze: " + probka1.subList(0, 5));
    }
}
Rozmiar wynosi ok. 1000 (około 1%), a obie próbki są identyczne. Deterministyczna próbka pozwala powtórzyć walidację po poprawce i porównać wyniki, a różne osoby sprawdzają te same rekordy - w przeciwieństwie do losowania bez ziarna.
